const results = [];

for (const item of items) {
  const row = item.json;

  const userId = row['Line_ID (ไอดีไลน์)'];
  if (!userId || userId.trim() === '') continue;

  const roomNo     = row['Room_No (เลขห้อง)']             || 'ไม่ระบุ';
  const tenantName = row['Name (ชื่อผู้เช่า)']            || 'ไม่ระบุชื่อ';
  const roomRate   = parseFloat(row['Room_Rate (ค่าห้อง)'])            || 0;
  const waterPrev  = parseFloat(row['Water_Prev (น้ำเดือนก่อน)'])      || 0;
  const waterNow   = parseFloat(row['Water_Now (น้ำเดือนนี้)'])        || 0;
  const elecPrev   = parseFloat(row['Elec_Prev (ไฟเดือนก่อน)'])       || 0;
  const elecNow    = parseFloat(row['Elec_Now (ไฟเดือนนี้)'])          || 0;
  const otherFee   = parseFloat(row['Other_Fee (ค่าอื่นๆ/ส่วนกลาง)']) || 0;

  const WATER_RATE = 12;
  const ELEC_RATE  = 4;

  const waterUnit = Math.max(waterNow - waterPrev, 0);
  const elecUnit  = Math.max(elecNow  - elecPrev,  0);
  const waterCost = waterUnit * WATER_RATE;
  const elecCost  = elecUnit  * ELEC_RATE;
  const totalCost = roomRate + waterCost + elecCost + otherFee;

  const now = new Date();
  const monthTH = now.toLocaleDateString('th-TH', { month: 'long', year: 'numeric' });

  const message = `🏠 แจ้งยอดชำระประจำ${monthTH}
🚪 ห้อง: ${roomNo} (${tenantName})
━━━━━━━━━━━━━━━━━
💵 ค่าเช่าห้อง: ${roomRate.toLocaleString()} บาท
💧 ค่าน้ำ (หน่วยละ ${WATER_RATE} บาท)
▸ ใช้ไป ${waterUnit} หน่วย : ${waterCost.toLocaleString()} บาท
⚡ ค่าไฟ (หน่วยละ ${ELEC_RATE} บาท)
▸ ใช้ไป ${elecUnit} หน่วย : ${elecCost.toLocaleString()} บาท
🔧 ค่าอื่นๆ/ส่วนกลาง: ${otherFee.toLocaleString()} บาท
━━━━━━━━━━━━━━━━━
💰 ยอดรวมทั้งสิ้น: ${totalCost.toLocaleString()} บาท
━━━━━━━━━━━━━━━━━
📱 ติดต่อเจ้าหน้าที่เพื่อสแกน QR Code ชำระเงินได้เลยครับ 🙏`;

  results.push({ json: { userId, roomNo, tenantName, totalCost, message } });
}

return results;

