const allItems = $input.all();
const announcements = allItems.filter(i => i.json['Announce']);
const tenants = allItems.filter(i => i.json['Line_ID (ไอดีไลน์)']);

if (announcements.length === 0 || tenants.length === 0) return [];

// เรียงตาม DATE&TIME ล่าสุดก่อน
const sorted = announcements.sort((a, b) =>
  new Date(b.json['DATE&TIME']) - new Date(a.json['DATE&TIME'])
);
const latestAnnounce = sorted[0].json;

// ถ้ามี Sent_At แล้ว = ส่งไปแล้ว → หยุด
if (latestAnnounce['Sent_At'] && String(latestAnnounce['Sent_At']).trim() !== '') {
  return [];
}

const now = new Date();
const announceDate = new Date(latestAnnounce['DATE&TIME']);

// ต้องเป็นวันนี้
const isToday =
  announceDate.getFullYear() === now.getFullYear() &&
  announceDate.getMonth()    === now.getMonth() &&
  announceDate.getDate()     === now.getDate();

// ต้องเพิ่งสร้างภายใน 3 นาที
const isFresh = (now - announceDate) / (1000 * 60) <= 3;

if (!isToday || !isFresh) return [];

const announceText = String(latestAnnounce['Announce']).trim();

return tenants.map(tenant => ({
  json: {
    userId: String(tenant.json['Line_ID (ไอดีไลน์)']).trim(),
    message: `📢 ประกาศจากนิติบุคคลโฆษิตนิวาส\n\nเรียนคุณ ${tenant.json['Name (ชื่อผู้เช่า)'] || 'ผู้พักอาศัย'}\n\n"${announceText}"`,
    announceText  // ← ส่งออกไปให้ Update Node ใช้ match
  }
}));

