const userId = $input.first().json.userId;
const message = $input.first().json.message;
const replyToken = $input.first().json.replyToken;

// ===== ตั้งค่า UID แอดมิน (เพิ่มได้เรื่อยๆ) =====
const ADMIN_UIDS = [
  'U60442cb02400ac426b3da6d1259479ab',  // แอดมิน 1
  'Ua25dc80da8f1de47f6652744a01e39bf',  // แอดมิน 2
  'U18a5400d3796f9161fed8b1c64fad2be',  // แอดมิน 3
];
// ===================================================

if (!ADMIN_UIDS.includes(userId)) {
  return [{ json: { skip: true, replyToken, reason: 'not_admin' } }];
}

if (!message.startsWith('!ประกาศ-')) {
  return [{ json: { skip: true, replyToken, reason: 'not_command' } }];
}

const announceText = message.replace('!ประกาศ-', '').trim();

if (!announceText) {
  return [{ json: { skip: true, replyToken, reason: 'empty_message' } }];
}

return [{ json: { skip: false, announceText, replyToken } }];

